<!DOCTYPE html>
<html>
<head>
  <meta charset="utf-8">
  <title>Kanban Board</title>
  <style>
    body { font-family: sans-serif; }
    #board { display: flex; width: 80%; margin: 20px auto; }
    #col-todo, #col-doing, #col-done { background-color: #f9f9f9; padding: 10px; border: 1px solid #ddd; flex: 1; }
    .count { font-weight: bold; margin-bottom: 5px; }
    .card { border: 1px solid #ccc; background-color: #fff; padding: 8px; cursor: grab; }
    .card-del { float: right; font-size: 16px; color: red; text-decoration: none; display: block;}
    #new-card, #add-card { margin-right: 5px; padding: 5px; }
  </style>
</head>
<body>

  <div id="board">
    <div id="col-todo" draggable="true">
      <h2>To Do</h2>
      <span class="count">0</span>
      <div id="card-container-todo"></div>
    </div>
    <div id="col-doing" draggable="true">
      <h2>Doing</h2>
      <span class="count">0</span>
      <div id="card-container-doing"></div>
    </div>
    <div id="col-done" draggable="true">
      <h2>Done</h2>
      <span class="count">0</span>
      <div id="card-container-done"></div>
    </div>
  </div>

  <input type="text" id="new-card" placeholder="New card title">
  <button id="add-card">Add Card</button>

  <script>
    const board = document.getElementById('board');
    const colTodo = document.getElementById('col-todo');
    const colDoing = document.getElementById('col-doing');
    const colDone = document.getElementById('col-done');
    const newCardInput = document.getElementById('new-card');
    const addCardButton = document.getElementById('add-card');
    const cardContainerTodo = document.getElementById('card-container-todo');
    const cardContainerDoing = document.getElementById('card-container-doing');
    const cardContainerDone = document.getElementById('card-container-done');

    let boardState = [];

    function loadBoard() {
      const storedState = localStorage.getItem('kanban_board');
      if (storedState) {
        boardState = JSON.parse(storedState);
      }
      updateColumnCounts();
      renderCards();
    }

    function saveBoard() {
      localStorage.setItem('kanban_board', JSON.stringify(boardState));
    }

    function updateColumnCounts() {
      const colTodoCount = cardContainerTodo.children.length;
      const colDoingCount = cardContainerDoing.children.length;
      const colDoneCount = cardContainerDone.children.length;

      document.querySelector('#col-todo .count').textContent = colTodoCount;
      document.querySelector('#col-doing .count').textContent = colDoingCount;
      document.querySelector('#col-done .count').textContent = colDoneCount;
    }


    function renderCards() {
      cardContainerTodo.innerHTML = '';
      cardContainerDoing.innerHTML = '';
      cardContainerDone.innerHTML = '';

      boardState.forEach((card, index) => {
        const cardElement = document.createElement('div');
        cardElement.classList.add('card');
        cardElement.id = `card-${index}`;
        cardElement.draggable="true";


        const title = card.title;
        const columnId = card.column;

        cardElement.textContent = title;

        const deleteButton = document.createElement('span');
        deleteButton.classList.add('card-del');
        deleteButton.textContent = 'x';
        cardElement.appendChild(deleteButton);


        if (columnId === 'todo') {
          cardContainerTodo.appendChild(cardElement);
        } else if (columnId === 'doing') {
          cardContainerDoing.appendChild(cardElement);
        } else {
          cardContainerDone.appendChild(cardElement);
        }
      });
    }

    function createCard() {
      const title = newCardInput.value.trim();
      if (title) {
        const newCard = { title: title, column: 'todo' };
        boardState.push(newCard);
        renderCards();
        updateColumnCounts();
        saveBoard();
        newCardInput.value = '';
        newCardInput.focus();
      }
    }

    function handleAddCard() {
      createCard();
    }

    function handleDrop(event) {
      const card = event.dataTransfer.getData('text/plain');
      const cardElement = document.getElementById(`card-${card}`);

      let newColumnId;
      if (event.target.id === 'col-todo') {
        newColumnId = 'todo';
      } else if (event.target.id === 'col-doing') {
        newColumnId = 'doing';
      } else {
        newColumnId = 'done';
      }

      const existingCardIndex = boardState.findIndex(card => card.title === cardElement.textContent);
      if (existingCardIndex !== -1) {
          boardState[existingCardIndex].column = newColumnId;
      }


      renderCards();
      updateColumnCounts();
      saveBoard();

    }

    addCardButton.addEventListener('click', handleAddCard);

    colTodo.addEventListener('dragover', (event) => {
        event.preventDefault();
    });

    colDoing.addEventListener('dragover', (event) => {
        event.preventDefault();
    });

    colDone.addEventListener('dragover', (event) => {
        event.preventDefault();
    });


    colTodo.addEventListener('drop', handleDrop);
    colDoing.addEventListener('drop', handleDrop);
    colDone.addEventListener('drop', handleDrop);



    loadBoard();

  </script>

</body>
</html>
